krpano.action:
if (krpano.xr_input_initialized) return;
krpano.xr_input_initialized = true;

var state = krpano.xr_input = {
  session: null,
  referenceSpace: null,
  sessionOwner: "none",
  referenceSpaceRequest: null,
  selectHandler: null,
  endHandler: null,
  timer: null,
  lastTarget: "",
  lastInput: "none"
};

function log(event, data) {
  try {
    if (window.__krpanoXRDebugLog) window.__krpanoXRDebugLog(event, data || {});
    else console.log("[XRInput]", event, data || {});
  } catch (e) {}
}

function normalizeTarget(target) {
  var name = typeof target === "string" ? target : (target && target.name ? target.name : "");
  return String(name || "").replace(/^hotspot\[/, "").replace(/\]$/, "");
}

function controllerForHand(handedness) {
  var hand = String(handedness || "").toLowerCase();
  var controllers = null;
  try { controllers = krpano.webvr && krpano.webvr.vrcontrollers; } catch (e) {}
  if (controllers && typeof controllers.length === "number") {
    for (var i = 0; i < controllers.length; i++) {
      if (String(controllers[i] && controllers[i].hand || "").toLowerCase() === hand) return controllers[i];
    }
  }
  try {
    var suffix = hand === "left" ? "l" : (hand === "right" ? "r" : "");
    if (suffix) return { hs: krpano.get("hotspot[vr_controller_" + suffix + "]") };
  } catch (e) {}
  return null;
}

function activeUiTarget(handedness) {
  var hand = String(handedness || "").toLowerCase();
  var controller = controllerForHand(hand);
  var target = normalizeTarget(controller && controller.hs ? controller.hs.target : null);
  if (target.indexOf("iu_gaze_btn_") === 0) return target;

  if (hand === "left" || hand === "right") return "";
  try {
    var active = krpano.webvr && krpano.webvr.activevrcontroller;
    target = normalizeTarget(active && active.hs ? active.hs.target : null);
    if (target.indexOf("iu_gaze_btn_") === 0) return target;
  } catch (e) {}
  return "";
}

function dispatchAction(action, source, target) {
  if (!action) return;
  state.lastTarget = target || "lesson-panel";
  state.lastInput = source;
  if (window.__krpanoImmersiveUiDispatch) window.__krpanoImmersiveUiDispatch(action);
  try {
    var active = krpano.webvr && krpano.webvr.activevrcontroller;
    if (active && active.hs && active.hs.pulse) active.hs.pulse(action === "mcqSubmit" ? 0.8 : 0.45, 0.05);
  } catch (e) {}
  log("select", { input: source, target: state.lastTarget, action: action });
}

function dispatchTarget(name, source) {
  var action = "";
  try { action = krpano.get("hotspot[" + name + "].dataaction") || ""; } catch (e) {}
  dispatchAction(action, source, name);
}

function dispatchHandRay(event, source) {
  var refs = krpano.immersive_ui_refs;
  var three = krpano.threejs;
  if (!refs || !refs.panel || !refs.panel.mesh || !three || !three.THREE || !source.targetRaySpace) return false;
  var frame = event && event.frame;
  var referenceSpace = state.referenceSpace;
  if (!frame || !referenceSpace || !frame.getPose) return false;

  var pose = null;
  try { pose = frame.getPose(source.targetRaySpace, referenceSpace); } catch (e) {}
  if (!pose || !pose.transform) return false;
  var transform = pose.transform;
  var position = transform.position;
  var orientation = transform.orientation;
  var THREE = three.THREE;
  var origin = new THREE.Vector3(position.x, position.y, position.z);
  var quaternion = new THREE.Quaternion(orientation.x, orientation.y, orientation.z, orientation.w);
  var direction = new THREE.Vector3(0, 0, -1).applyQuaternion(quaternion).normalize();
  var hits = new THREE.Raycaster(origin, direction, 0, 50).intersectObject(refs.panel.mesh, false);
  if (!hits || !hits.length || !hits[0].uv) return false;

  var cx = hits[0].uv.x * 2048;
  var cy = (1 - hits[0].uv.y) * 1280;
  var regions = refs.buttonRegions || [];
  for (var i = regions.length - 1; i >= 0; i--) {
    var region = regions[i];
    if (!region || !region.action) continue;
    if (cx >= region.x - 20 && cx <= region.x + region.w + 20 && cy >= region.y - 20 && cy <= region.y + region.h + 20) {
      refs.hoverAction = region.action;
      if (refs.panel.draw) refs.panel.draw();
      dispatchAction(region.action, "hand-pinch-ray", "lesson-panel");
      return true;
    }
  }
  return false;
}

function findSessionBinding() {
  var rendererSession = null;
  var referenceSpace = null;
  try {
    var xr = krpano.threejs && krpano.threejs.renderer && krpano.threejs.renderer.xr;
    if (xr) {
      rendererSession = xr.getSession();
      referenceSpace = xr.getReferenceSpace();
    }
  } catch (e) {}
  if (rendererSession) return { session: rendererSession, referenceSpace: referenceSpace, owner: "threejs" };

  var webvrSession = null;
  try { webvrSession = krpano.webvr && (krpano.webvr.session || krpano.webvr.xrSession); } catch (e) {}
  return webvrSession ? { session: webvrSession, referenceSpace: null, owner: "krpano-webvr" } : null;
}

function ensureReferenceSpace(session) {
  if (!session || !session.requestReferenceSpace || state.referenceSpace || state.referenceSpaceRequest) return;
  var requestedSession = session;
  state.referenceSpaceRequest = session.requestReferenceSpace("local-floor")
    .catch(function() { return requestedSession.requestReferenceSpace("local"); })
    .then(function(referenceSpace) {
      if (state.session === requestedSession) {
        state.referenceSpace = referenceSpace;
        log("hand-ray-ready", { owner: state.sessionOwner });
      }
    })
    .catch(function(error) {
      log("hand-ray-unavailable", { owner: state.sessionOwner, message: String(error && error.message || error) });
    })
    .then(function() {
      if (state.session === requestedSession) state.referenceSpaceRequest = null;
    });
}

function detachSession() {
  if (state.session && state.session.removeEventListener) {
    try { if (state.selectHandler) state.session.removeEventListener("select", state.selectHandler); } catch (e) {}
    try { if (state.endHandler) state.session.removeEventListener("end", state.endHandler); } catch (e) {}
  }
  state.session = null;
  state.referenceSpace = null;
  state.sessionOwner = "none";
  state.referenceSpaceRequest = null;
  state.selectHandler = null;
  state.endHandler = null;
}

function attachSession() {
  var binding = findSessionBinding();
  var session = binding && binding.session;
  if (!session || !session.addEventListener) return;
  if (session === state.session) {
    if (binding.referenceSpace) state.referenceSpace = binding.referenceSpace;
    state.sessionOwner = binding.owner;
    ensureReferenceSpace(session);
    return;
  }
  detachSession();
  state.session = session;
  state.referenceSpace = binding.referenceSpace;
  state.sessionOwner = binding.owner;
  state.selectHandler = function(event) {
    var source = event && event.inputSource ? event.inputSource : null;
    if (!source || !source.hand) return;
    var target = activeUiTarget(source.handedness);
    if (target) dispatchTarget(target, "hand-pinch");
    else dispatchHandRay(event, source);
  };
  state.endHandler = function() { detachSession(); };
  session.addEventListener("select", state.selectHandler);
  session.addEventListener("end", state.endHandler);
  ensureReferenceSpace(session);
  log("hand-pinch-ready", {});
}

function updateDiagnostics() {
  var controllers = [];
  try {
    var list = krpano.webvr && krpano.webvr.vrcontrollers;
    if (list && typeof list.length === "number") {
      for (var i = 0; i < list.length; i++) {
        var item = list[i] || {};
        controllers.push({ hand: item.hand || "", target: normalizeTarget(item.hs && item.hs.target) });
      }
    }
  } catch (e) {}
  window.__krpanoXRDiagnostics = {
    inVr: !!(krpano.webvr && krpano.webvr.isenabled),
    isWebXr: !!(krpano.webvr && krpano.webvr.iswebxr),
    controllers: controllers,
    handSelectAttached: !!state.session,
    handRayReady: !!state.referenceSpace,
    sessionOwner: state.sessionOwner,
    lastTarget: state.lastTarget,
    lastInput: state.lastInput
  };
}

function refresh() {
  try {
    if (krpano.webvr) {
      krpano.webvr.vr_controller_support = true;
      krpano.webvr.vr_controller_clickbuttons = "0,1";
      krpano.webvr.vr_controller_activationbuttons = "0,1";
    }
  } catch (e) {}
  attachSession();
  updateDiagnostics();
}

function cleanup() {
  if (state.timer) {
    clearInterval(state.timer);
    state.timer = null;
  }
  detachSession();
  window.__xrHaptic = undefined;
  window.__krpanoXRDiagnostics = undefined;
  krpano.xr_input_refresh = null;
  krpano.xr_input_cleanup = null;
  krpano.xr_input_initialized = false;
}

window.__xrHaptic = function(eventType) {
  try {
    var active = krpano.webvr && krpano.webvr.activevrcontroller;
    if (!active || !active.hs || !active.hs.pulse) return;
    var intensity = eventType === "confirm" ? 0.8 : 0.45;
    active.hs.pulse(intensity, eventType === "confirm" ? 0.08 : 0.04);
  } catch (e) {}
};

krpano.xr_input_refresh = refresh;
krpano.xr_input_cleanup = cleanup;
refresh();
state.timer = setInterval(refresh, 400);
log("ready", {});
